Move this feed fetch onto Data Client. `PostView` (an Entity, `@/schemas/PostView`) exists, `DataProvider` wraps the app, and `client` is the app's threadiverse SDK instance. Write the endpoint in src/features/feed/endpoints.ts and rewrite the component to read through it. Keep the current behavior: switching sort aborts the request for the old sort.

```tsx
// src/features/feed/CommunityFeed.tsx
import { useEffect, useState } from 'react';
import { client } from '@/services/client';
import type { PostView } from '@/schemas/PostView';
import PostList from './PostList';

export default function CommunityFeed({ community, sort }: { community: string; sort: string }) {
  const [posts, setPosts] = useState<PostView[]>();
  useEffect(() => {
    const controller = new AbortController();
    client
      .getPosts({ community_name: community, sort, signal: controller.signal })
      .then(res => setPosts(res.posts));
    return () => controller.abort();
  }, [community, sort]);
  if (!posts) return <Spinner />;
  return <PostList posts={posts} />;
}
```
